    "base_model": "qwen3.5:9b-q4_K_M",
    "expected_base_model_id": "6488c96fa5fa",
    "runtime_model": "nettap-ai:0.4.0-rc.1",
    "source_policy": "model/nettap-ai.Modelfile",
